import re, pathlib
path = pathlib.Path('src/fmt_fp.c')
src = path.read_text()

new_func = r'''
int
mrb_format_float(mrb_float f, char *buf, size_t buf_size, char fmt, int prec, char sign) {
  if (buf_size == 0) {
    return 0;
  }

  char *s = buf;
  char *end = buf + buf_size - 1; /* last valid position for the terminating NUL */
  int buf_remaining = (int)buf_size - 1;
  int alt_form = 0;

#define PUTC(ch) do { \
  if (s >= end) goto out; \
  *s++ = (ch); \
} while (0)

  if ((uint8_t)fmt & 0x80) {
    fmt &= 0x7f;  /* turn off alt_form flag */
    alt_form = 1;
  }
  if (buf_size <= FLT_MIN_BUF_SIZE) {
    /* Smallest exp notion is -9e+99 (-9e+199) which is 6 (7) chars plus terminating
       null. */

    if (buf_size >= 2) {
      PUTC('?');
    }
    *s = '\0';
    return (int)(s - buf);
  }
  if (signbit(f)) {
    PUTC('-');
    f = -f;
  } else if (sign) {
    PUTC(sign);
  }
  buf_remaining -= (int)(s - buf); // Adjust for sign

  {
    char uc = fmt & 0x20;
    if (isinf(f)) {
      PUTC('I' ^ uc);
      PUTC('N' ^ uc);
      PUTC('F' ^ uc);
      goto out;
    } else if (isnan(f)) {
      PUTC('N' ^ uc);
      PUTC('A' ^ uc);
      PUTC('N' ^ uc);
      goto out;
    }
  }

  if (prec < 0) {
    prec = 6;
  }
  char e_char = 'E' | (fmt & 0x20);   // e_char will match case of fmt
  fmt |= 0x20; // Force fmt to be lowercase
  char org_fmt = fmt;
  if (fmt == 'g' && prec == 0) {
    prec = 1;
  }
  int e, e1;
  int dec = 0;
  char e_sign = '\0';
  int num_digits = 0;
  const mrb_float *pos_pow = g_pos_pow;
  const mrb_float *neg_pow = g_neg_pow;

  if (f == 0.0) {
    e = 0;
    if (fmt == 'e') {
      e_sign = '+';
    } else if (fmt == 'f') {
      num_digits = prec + 1;
    }
  } else if (f < 1.0) { // f < 1.0
    char first_dig = '0';
    if (f >= FLT_ROUND_TO_ONE) {
      first_dig = '1';
    }

    // Build negative exponent
    for (e = 0, e1 = FLT_DECEXP; e1; e1 >>= 1, pos_pow++, neg_pow++) {
      if (*neg_pow > f) {
        e += e1;
        f *= *pos_pow;
      }
    }
    char e_sign_char = '-';
    if (f < 1.0) {
      if (f >= FLT_ROUND_TO_ONE) {
        f = 1.0;
        if (e == 0) {
          e_sign_char = '+';
        }
      } else {
        e++;
        f *= 10.0;
      }
    }

    // If the user specified 'g' format, and e is <= 4, then we'll switch
    // to the fixed format ('f')

    if (fmt == 'f' || (fmt == 'g' && e <= 4)) {
      fmt = 'f';
      dec = -1;
      PUTC(first_dig);

      if (prec + e + 1 > buf_remaining) {
        prec = buf_remaining - e - 1;
      }

      if (org_fmt == 'g') {
        prec += (e - 1);
      }
      num_digits = prec;
      if (num_digits || alt_form) {
        PUTC('.');
        while (--e && num_digits) {
          PUTC('0');
          num_digits--;
        }
      }
    } else {
      // For e & g formats, we'll be printing the exponent, so set the
      // sign.
      e_sign = e_sign_char;
      dec = 0;

      if (prec > (buf_remaining - FLT_MIN_BUF_SIZE)) {
        prec = buf_remaining - FLT_MIN_BUF_SIZE;
        if (fmt == 'g') {
          prec++;
        }
      }
    }
  } else {
    // Build positive exponent
    for (e = 0, e1 = FLT_DECEXP; e1; e1 >>= 1, pos_pow++, neg_pow++) {
      if (*pos_pow <= f) {
        e += e1;
        f *= *neg_pow;
      }
    }

    // If the user specified fixed format (fmt == 'f') and e makes the
    // number too big to fit into the available buffer, then we'll
    // switch to the 'e' format.

    if (fmt == 'f') {
      if (e >= buf_remaining) {
        fmt = 'e';
      } else if ((e + prec + 2) > buf_remaining) {
        prec = buf_remaining - e - 2;
        if (prec < 0) {
          // This means no decimal point, so we can add one back
          // for the decimal.
          prec++;
        }
      }
    }
    if (fmt == 'e' && prec > (buf_remaining - 6)) {
      prec = buf_remaining - 6;
    }
    // If the user specified 'g' format, and e is < prec, then we'll switch
    // to the fixed format.

    if (fmt == 'g' && e < prec) {
      fmt = 'f';
      prec -= (e + 1);
    }
    if (fmt == 'f') {
      dec = e;
      num_digits = prec + e + 1;
    } else {
      e_sign = '+';
    }
  }
  if (prec < 0) {
    // This can happen when the prec is trimmed to prevent buffer overflow
    prec = 0;
  }

  // We now have f as a floating point number between >= 1 and < 10
  // (or equal to zero), and e contains the absolute value of the power of
  // 10 exponent. and (dec + 1) == the number of dgits before the decimal.

  // For e, prec is # digits after the decimal
  // For f, prec is # digits after the decimal
  // For g, prec is the max number of significant digits
  //
  // For e & g there will be a single digit before the decimal
  // for f there will be e digits before the decimal

  if (fmt == 'e') {
    num_digits = prec + 1;
  } else if (fmt == 'g') {
    if (prec == 0) {
      prec = 1;
    }
    num_digits = prec;
  }

  // Print the digits of the mantissa
  for (int i = 0; i < num_digits; ++i, --dec) {
    int8_t d = f;
    PUTC('0' + d);
    if (dec == 0 && (prec > 0 || alt_form)) {
      PUTC('.');
    }
    f -= (mrb_float)d;
    f *= 10.0;
  }

  // Round
  if (f >= 5.0) {
    char *rs = s;
    rs--;
    while (1) {
      if (*rs == '.') {
        rs--;
        continue;
      }
      if (*rs < '0' || *rs > '9') {
        // + or -
        rs++; // So we sit on the digit to the right of the sign
        break;
      }
      if (*rs < '9') {
        (*rs)++;
        break;
      }
      *rs = '0';
      if (rs == buf) {
        break;
      }
      rs--;
    }
    if (*rs == '0') {
      // We need to insert a 1
      if (rs[1] == '.' && fmt != 'f') {
        // We're going to round 9.99 to 10.00
        // Move the decimal point
        rs[0] = '.';
        rs[1] = '0';
        if (e_sign == '-') {
          e--;
        } else {
          e++;
        }
      }
      if (s >= end) goto out;
      s++;
      char *ss = s;
      while (ss > rs) {
        *ss = ss[-1];
        ss--;
      }
      *rs = '1';
      if (f < 1.0 && fmt == 'f') {
        // We rounded up to 1.0
        prec--;
      }
    }
  }

  if (org_fmt == 'g' && prec > 0 && !alt_form) {
    // Remove trailing zeros and a trailing decimal point
    while (s > buf && s[-1] == '0') {
      s--;
    }
    if (s > buf && s[-1] == '.') {
      s--;
    }
  }
  // Append the exponent
  if (e_sign) {
    PUTC(e_char);
    PUTC(e_sign);
    if (e >= 100) {
      PUTC('0' + (e / 100));
      e %= 100;
    }
    PUTC('0' + (e / 10));
    PUTC('0' + (e % 10));
  }

out:
  /* always terminate without writing past the provided buffer */
  if (s > end) {
    s = end;
  }
  *s = '\0';

#undef PUTC
  return (int)(s - buf);
}
'''

# Replace the whole mrb_format_float function definition.
pattern = re.compile(r"\nint\nmrb_format_float\(mrb_float f, char \*buf, size_t buf_size, char fmt, int prec, char sign\) \{.*?\n\}\n", re.S)
new_src, n = pattern.subn('\n' + new_func + '\n', src, count=1)
if n != 1:
    raise SystemExit(f'Failed to replace mrb_format_float (matches={n})')

# Replace unsafe strcat in mrb_float_to_str
new_src2, n2 = re.subn(r"\n\s*strcat\(buf, \\\"\\.0\\\"\);\n",
                       "\n  {\n    size_t len = strlen(buf);\n    if (len + 2 < sizeof(buf)) {\n      buf[len] = '.';\n      buf[len+1] = '0';\n      buf[len+2] = '\\0';\n    }\n    else {\n      buf[sizeof(buf)-1] = '\\0';\n    }\n  }\n",
                       new_src, count=1)
if n2 != 1:
    raise SystemExit(f'Failed to replace strcat(buf, ".0") (matches={n2})')

path.write_text(new_src2)
print('patched', path)
